mapper.select:
/* com.shop.mapper.VendorProduct.selectVendorProductList */ SELECT TP.ID AS id , TP.PROD_NM AS prodNm , ( SELECT D.SYS_FILE_NM FROM TB_FILE_DET D WHERE D.FILE_ID = TP.REP_FILE_ID AND D.FILE_SEQ = 1 AND D.DEL_YN = 'N' ) AS repSysFileNm , CONCAT( CASE WHEN TP.IS_SPRING = 'Y' THEN 'S' ELSE '_' END, CASE WHEN TP.IS_SUMMER = 'Y' THEN 'S' ELSE '_' END, CASE WHEN TP.IS_AUTUMN = 'Y' THEN 'F' ELSE '_' END, CASE WHEN TP.IS_WINTER = 'Y' THEN 'W' ELSE '_' END ) AS season , TPD.prodColors , TPD.prodSizes FROM TB_PRODUCT TP INNER JOIN ( SELECT PRODUCT_ID , STRING_AGG(PRODUCT_DET_COLOR, ',') AS prodColors , STRING_AGG(DISTINCT PRODUCT_DET_SIZE, ',') AS prodSizes FROM TB_PRODUCT_DET WHERE DEL_YN = 'N' GROUP BY PRODUCT_ID ) TPD ON TPD.PRODUCT_ID = TP.ID
AND TP.DEL_YN = 'N'
AND TP.VENDOR_ID = #{vendorId}
AND TP.PARTNER_ID = #{partnerId}
ORDER BY TP.ID DESC
